const POOLS={hbl:{regular:[["校隊輪替","教練把最後兩分鐘交給你處理。"],["縣市預賽","對手針對你的主要武器設計防守。"],["學長與新人","球權與防守責任必須重新分配。"],["全國八強門票","一場比賽同時影響球隊戰績與升學曝光。"]],special:[["球探坐上看台","大學教練第一次完整記錄你的比賽。"],["隊友爭位","同位置隊友的進步改變了原本輪替。"],["代表作機會","強隊把防守重心放到你身上。"]]},college:{regular:[["大學輪替競爭","更快、更強的比賽迫使你重新定義角色。"],["客場連戰","課業、旅程與恢復同時壓縮準備時間。"],["球隊戰術改版","教練要求你承擔不同於高中的工作。"],["跨區邀請賽","不同球風讓球探重新評估你的上限。"]],special:[["先發席次鬆動","一場訓練賽改變了原本穩定的輪替。"],["國家培訓觀察","這只是觀察名單，不等於正式入選。"],["轉學與留隊聲音","外界開始討論你的下一個發展環境。"]]},pro:{regular:[["戰術角色調整","球隊要求你在球權與防守責任間重新取捨。"],["投籃低潮","對手開始放大你最近幾場的效率問題。"],["影片會議","教練逐回合指出你能留在輪替的細節。"],["關鍵第四節","比賽最後六分鐘決定下一週的角色。"],["主場壓力","觀眾與媒體開始質疑球隊給你的定位。"],["隊友合約年","隊內競爭不再只是上場時間，也影響未來名單。"]],special:[["交易傳聞","市場詢價迫使球隊重新確認你的價值。"],["國家隊窗口","聯盟球季與國家隊責任出現衝突。"],["季後賽對位","系列賽連續針對你的弱點。"],["新秀加入","更年輕的同位置球員進入輪替。"]]},veteran:{regular:[["負荷管理","球隊需要你的經驗，也擔心恢復速度。"],["角色交棒","新秀開始接手你熟悉的球權與任務。"],["回到母隊的聲音","熟悉的城市重新出現在市場討論。"],["季後賽老將價值","短輪替讓判斷與健康同樣重要。"]],special:[["最後一份長約","球隊只願意用短約換取你的即戰力。"],["導師責任","年輕隊友開始直接向你尋求答案。"],["生涯收束","你必須決定還想用什麼方式留下。"]]}};
function hash(value){return [...String(value)].reduce((sum,char)=>(sum*33+char.charCodeAt(0))>>>0,5381)}function parse(value,fallback={}){try{return JSON.parse(value||"")}catch{return fallback}}function pick(list,key){return list[hash(key)%list.length]}function roomCode(){const alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789",bytes=new Uint8Array(6);crypto.getRandomValues(bytes);return [...bytes].map(byte=>alphabet[byte%alphabet.length]).join("")}function stageFor(c){const age=Number(c.age);if(c.league==="HBL"&&age<=18)return"hbl";if(age>=35)return"veteran";if(age>=23||Number(c.contract_years)>0||!STUDENT_LEAGUES.has(c.league))return"pro";return"college"}function stageLabel(s){return{hbl:"HBL",college:"大學生涯",pro:"職業生涯",veteran:"老將生涯"}[s]}function sharedSeason(w){return Number(w.cycle_number)%3===0}
async function roomRow(env,code){return env.DB.prepare("SELECT * FROM online_key_battle_rooms WHERE room_code=?").bind(code).first()}async function worldRow(env,code){return env.DB.prepare("SELECT * FROM online_shared_worlds WHERE room_code=?").bind(code).first()}async function lobbyPlayers(env,code){return(await env.DB.prepare("SELECT p.user_id,p.nickname,p.role,c.origin_route,c.player_name FROM online_key_battle_players p JOIN online_shared_player_careers c ON c.room_code=p.room_code AND c.user_id=p.user_id WHERE p.room_code=? ORDER BY p.joined_at").bind(code).all()).results||[]}async function careerRows(env,code){return(await env.DB.prepare("SELECT user_id,player_name,position,origin_route,league,team_name,age,overall,health,reputation,draft_stock,contract_years,career_flags,last_result,updated_at FROM online_shared_player_careers WHERE room_code=? ORDER BY position").bind(code).all()).results||[]}
async function sharedWorldEpilogue(env,code,rows=null){const careers=rows||await careerRows(env,code);if(!careers.length||careers.some(row=>!parse(row.career_flags,{}).retired))return null;const history=(await env.DB.prepare("SELECT cycle_number,chapter_number,result FROM online_shared_history WHERE room_code=? AND chapter_number IN (45,90) ORDER BY cycle_number,chapter_number").bind(code).all()).results||[],events=new Map();for(const row of history){const key=`${row.cycle_number}:${row.chapter_number}`,result=parse(row.result,{});if(!events.has(key))events.set(key,result)}let cooperation=0,jointAchievements=0,rivalries=0;const competitive=new Set(["hbl_match","college_showcase","pro_matchup","story_rivalry","story_championship","pro_regular","pro_playoffs","pro_finals"]);for(const result of events.values()){const delta=Number(result.shared?.cooperationDelta)||0;cooperation+=delta;if(result.commonOutcome==="success"&&delta>0)jointAchievements++;if(competitive.has(result.eventType||result.shared?.eventType))rivalries++}const retiredYears=careers.map(row=>Number(parse(row.career_flags,{}).retiredYear)||Number(row.updated_at?.slice?.(0,4))||2026),startYear=2026,endYear=Math.max(...retiredYears);return{title:"這個共享世界完成了最後一季",detail:`${careers.map(row=>row.player_name).join("、")} 都已結束球員生涯；合作、競爭與告別已封存為同一條時間線。`,years:`${startYear}–${endYear}`,events:events.size,cooperation,jointAchievements,rivalries,players:careers.map(row=>({player_name:row.player_name,team_name:row.team_name,league:row.league,age:+row.age,overall:+row.overall,retiredYear:Number(parse(row.career_flags,{}).retiredYear)||endYear}))}}
function collegeOptions(c){const o=[{id:"uba",label:"進入 UBA 一級",detail:"穩定升學路線，保留本土發展空間。"}];if(+c.reputation>=27)o.push({id:"uba_elite",label:"接受 UBA 強權招募",detail:"爭冠資源完整，上場競爭也更激烈。"});if(+c.draft_stock>=16)o.push({id:"ncaa_d2",label:"接受 NCAA D2 招募",detail:"赴美靠實際表現爭取更高層級。"});if(+c.health>=88)o.push({id:"japan_college",label:"接受日本大學獎學金",detail:"適應新的球隊與生活制度。"});if(+c.draft_stock>=25)o.push({id:"ncaa_d1",label:"接受 NCAA D1 招募",detail:"挑戰最高層級大學賽事與球探競爭。"});return o}
function eventFor(w,c){const ch=+w.chapter_number,cy=+w.cycle_number,s=stageFor(c),key=`${w.world_seed}:${c.user_id}:${cy}:${ch}`;if(ch===1)return{id:`${s}_training_${cy}`,eyebrow:`${stageLabel(s)}・季前訓練`,title:`${c.team_name} 的第 ${cy} 季準備開始`,detail:`你要以 ${ROLE_LABEL[c.position]} 身分決定本季成長方向；結果只寫入自己的球員。`,scope:"personal",options:OPTIONS.training,chapter_label:FLOW[0]};if(ch===2||ch===3&&!sharedSeason(w)){const kind=ch===2?"regular":"special",row=pick(POOLS[s][kind],`${key}:${kind}`),i=POOLS[s][kind].indexOf(row);return{id:`${s}_${kind}_${i}`,eyebrow:`${stageLabel(s)}・${ch===2?"一般事件":"特殊事件"}`,title:row[0],detail:`${row[1]} 目前球隊：${c.team_name}；你的選擇不會替其他玩家決定。`,scope:"personal",options:OPTIONS.event,chapter_label:FLOW[ch-1]}}if(ch===3)return{id:`shared_${s}_${cy}`,eyebrow:"共享世界・合理交會",title:s==="hbl"?"同屆球員在全國賽與培訓名單交會":s==="college"?"不同大學路線在國家培訓窗口交會":"不同聯盟在休賽期邀請賽與國家隊窗口交會",detail:"只有同一年且賽程合理時才同步停下；你們仍可效力不同球隊與聯盟。",scope:"intersection",options:OPTIONS.shared,chapter_label:FLOW[2]};if(ch===4)return{id:`health_${+c.health<60?"pressure":"routine"}`,eyebrow:`${stageLabel(s)}・健康管理`,title:+c.health<60?"醫療團隊要求你重新評估出賽負荷":"球季中段的疲勞開始影響訓練品質",detail:`目前健康 ${c.health}。恢復、調整與帶傷維持角色都有明確代價。`,scope:"personal",options:OPTIONS.health,chapter_label:FLOW[3]};if(ch===5){const row=pick([["關鍵賽段","球隊進入決定排名與角色的最後階段。"],["球季代表戰","本季最重要的對位會影響最終評價。"],["季末連戰","健康、效率與勝負必須同時管理。"]],`${key}:results`);return{id:`results_${hash(row[0])}`,eyebrow:`${stageLabel(s)}・球季結算`,title:row[0],detail:`${row[1]} 前四個階段留下的 OVR、健康與評價都會進入結果。`,scope:"personal",options:OPTIONS.results,chapter_label:FLOW[4]}}if(s==="hbl"&&+c.age===18)return{id:"hbl_graduation",eyebrow:"生涯抉擇・高中畢業",title:"HBL 三年履歷換來的升學邀請已經到齊",detail:"邀請依你的評價、健康與球探聲量開放，不保證每名玩家相同。",scope:"personal",options:collegeOptions(c),chapter_label:FLOW[5]};if(s==="college"&&+c.age===22)return{id:"pro_entry",eyebrow:"生涯抉擇・職業入口",title:`你從 ${c.league} 的 ${c.team_name} 進入職業市場`,detail:"目前 OVR、健康與球探聲量會直接影響第一份職業履歷。",scope:"personal",options:OPTIONS.pro,chapter_label:FLOW[5]};if(s==="pro"||s==="veteran")return{id:`contract_${s}_${cy}`,eyebrow:"生涯抉擇・合約市場",title:+c.contract_years>1?"有效合約仍在，但球隊要重新確認下季角色":"球季結束後，市場提出下一份條件",detail:"續留、談判或回到台灣市場只影響自己的生涯。",scope:"personal",options:OPTIONS.contract,chapter_label:FLOW[5]};return{id:`points_${s}_${cy}`,eyebrow:`${stageLabel(s)}・能力分配`,title:"把本季累積轉成下一季真正能使用的能力",detail:"能力、身體與球商三條方向都有不同的長期效果。",scope:"personal",options:OPTIONS.points,chapter_label:FLOW[5]}}
function choiceResult(w,c,e,choice){let overall=0,health=0,reputation=0,draft=0,contract=+c.contract_years,league=c.league,team=c.team_name,age=+c.age,title="",detail="";const fx={train_skill:[2,-5,2,2],train_team:[1,-2,5,1],train_recover:[0,8,1,0],risk:[1,-6,6,5],steady:[1,-2,4,2],support:[0,1,6,1],rest:[0,12,-1,-1],rehab:[1,7,1,0],play_through:[1,-10,5,4],push:[2,-8,6,5],execute:[1,-3,7,3],manage:[0,8,3,1],points_skill:[2,-2,1,2],points_body:[1,7,1,0],points_iq:[1,1,5,2],challenge:[1,-5,6,5],connect:[0,2,5,2],protect:[0,8,-1,-1]};if(fx[choice]){[overall,health,reputation,draft]=fx[choice];title=`「${e.options.find(x=>x.id===choice)?.label}」成為本階段的正式結果`;detail=`OVR ${overall>=0?"+":""}${overall}、健康 ${health>=0?"+":""}${health}、評價 ${reputation>=0?"+":""}${reputation}；後續事件會讀取這些狀態。`}if(["uba","uba_elite","ncaa_d2","japan_college","ncaa_d1"].includes(choice)){const p={uba:"UBA",uba_elite:"UBA 強權",ncaa_d2:"NCAA D2",japan_college:"日本大學",ncaa_d1:"NCAA D1"}[choice];league=p;team=COLLEGE_TEAMS[p][hash(`${c.user_id}:${p}`)%COLLEGE_TEAMS[p].length];overall=p==="NCAA D1"?3:2;health=p.includes("NCAA")?-5:-3;reputation=p==="UBA 強權"?6:4;draft=p==="NCAA D1"?10:p==="NCAA D2"?7:4;title=`你接受 ${team} 的正式招募`;detail=`${p} 成為接下來逐季進行的大學路線，不會直接跳過四年。`}if(choice==="domestic"){overall=2;reputation=5;draft=3;league="台灣職籃";team=PRO_TEAMS[hash(`${c.user_id}:domestic`)%PRO_TEAMS.length];contract=2;title=`你進入 ${team} 的新人名單`;detail="第一份職業合約成立，下一季開始逐季處理角色與比賽。"}if(choice==="development"){overall=3;health=-7;reputation=6;draft=8;league="NBA G League";team="灣岸發展隊";contract=1;title="你取得 G League 訓練營與名單入口";detail="這不是 NBA 保證合約，下一季仍要靠實際表現留隊。"}if(choice==="overseas"){overall=3;health=-6;reputation=7;draft=6;league="海外職業育成";team="東亞發展隊";contract=2;title="海外合約讓你正式進入職業生涯";detail="不同聯盟經驗會進入後續事件條件。"}if(choice==="accept"){contract=Math.max(2,contract);reputation=3;title=`你接受 ${team} 的下季條件`;detail="合約確定，角色仍會依下一季表現調整。"}if(choice==="negotiate"){const ok=+c.reputation + +c.draft_stock>=75;contract=ok?3:1;reputation=ok?5:-5;title=ok?"談判換到更長合約與明確角色":"球隊只願意保留一年短約";detail=ok?"前面球季累積的市場地位實際進入談判。":"要求不是免費選項，履歷不足時會承受代價。"}if(choice==="return"){contract=2;league="台灣職籃";team=PRO_TEAMS[hash(`${c.user_id}:return:${w.cycle_number}`)%PRO_TEAMS.length];reputation=4;title=`你回到台灣職業市場，加入 ${team}`;detail="放棄部分海外聲量，換取更清楚的本土輪替。"}return{title,detail,overall,health,reputation,draft,contract,league,team,age,event_id:e.id,choice}}
